using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class DelegationMissionTests
{
    static WorldSession New(bool refuses=false,long until=long.MaxValue)=>new(DelegationMission.Create(refuses:refuses,until:until));
    static void At(WorldSession s,long at){while(s.Seconds<at){s.SetPaused(false);long before=s.Seconds;s.AdvanceTo(at);Assert.True(s.Seconds>before);}}
    static RegionalRequest Send(WorldSession s,string id="request:delegate",RegionalAction action=RegionalAction.Move){var r=DelegationMission.Build(s.DiagnosticSnapshot(),id,action);Assert.Equal(ResultCode.Accepted,s.IssueRegional(r,s.Revision).Code);return r;}
    static long Due(WorldSession s,string message){var w=s.DiagnosticSnapshot();return w.Region!.Deliveries.Single(d=>w.Messaging.Attempts.Single(a=>a.Id==d.Attempt).MessageId==message).DueAt;}
    static string Order(WorldSession s,EntityId id)=>s.DiagnosticSnapshot().Region!.Commands.Single(c=>c.Request.Id==id).Message;
    static string Reply(WorldSession s,EntityId id)=>s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="region-report"&&m.CorrelationId==id.Value).Id;
    static long ArrivalTime(WorldSession s,EntityId id)=>s.DiagnosticSnapshot().Delegation!.Plans.Single(p=>p.Directive==id).Units.SelectMany(u=>u.Route).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max();
    [Fact] public void OwnerAndExistingServiceAreNotTransferred(){var w=DelegationMission.Create();Assert.Equal(2,w.CommandMandates!.Length);Assert.Equal(w.Region!.Units.First(u=>u.Commander==ContractFixture.Clerk).Home,w.Delegation!.Terms.KnownAddress);Assert.All(w.Units.Where(u=>u.Commander==ContractFixture.Clerk),u=>Assert.Equal(new EntityId("org:house"),u.Organization));Assert.Contains(w.ServiceBonds,b=>b.Subject==ContractFixture.Clerk&&b.Target==ContractFixture.Officer);Assert.DoesNotContain(w.ServiceBonds,b=>b.Subject==ContractFixture.Clerk&&b.Target==w.PlayerControl);Assert.Equal(100,w.Units.Where(u=>u.Commander==w.PlayerControl).Sum(u=>u.Soldiers));}
    [Fact] public void DeclaredCampIsAnAddressNotAnOmniscientMapObservation(){var s=New();Assert.DoesNotContain(RegionalBattle.View(s.DiagnosticSnapshot(),s.PlayerControl),v=>DelegationMission.Units.Contains(v.Unit));var r=Send(s);Assert.Equal(DelegationMission.Terms(long.MaxValue).KnownAddress,s.DiagnosticSnapshot().Region!.Commands.Single().Address);Assert.Empty(s.DiagnosticSnapshot().Delegation!.Plans);Assert.Equal("発送済・結果未確認",DelegationMission.View(s,s.PlayerControl).Single().Receipt);}
    [Fact] public void ReceiptAndActualArrivalUseDifferentPhysicalReturns(){var s=New();var r=Send(s);long delivery=Due(s,Order(s,r.Id));At(s,delivery-1);Assert.Empty(s.DiagnosticSnapshot().Delegation!.Plans);At(s,delivery);Assert.Single(s.DiagnosticSnapshot().Delegation!.Plans);Assert.Empty(s.DiagnosticSnapshot().Delegation!.Arrivals);Assert.Equal("発送済・結果未確認",DelegationMission.View(s,s.PlayerControl).Single().Receipt);long ack=Due(s,Reply(s,r.Id));At(s,ack);Assert.Equal("applied",DelegationMission.View(s,s.PlayerControl).Single().Receipt);Assert.Equal("到達の返報は未確認",DelegationMission.View(s,s.PlayerControl).Single().Progress);long arrived=ArrivalTime(s,r.Id);At(s,Math.Max(arrived,s.Seconds));var report=s.DiagnosticSnapshot().Delegation!.Arrivals.Single();Assert.Equal("到達の返報は未確認",DelegationMission.View(s,s.PlayerControl).Single().Progress);At(s,Due(s,report.Message));Assert.Equal("配置到達の申告",DelegationMission.View(s,s.PlayerControl).Single().Progress);Assert.Equal("責任・処分は未審査",DelegationMission.View(s,s.PlayerControl).Single().Responsibility);Assert.Contains(RegionalBattle.View(s.DiagnosticSnapshot(),s.PlayerControl),v=>DelegationMission.Units.Contains(v.Unit)&&v.ObservedAt==report.At&&!v.Live);}
    [Fact] public void PrivateRefusalIsNotVisibleUntilReplyArrives(){var a=New();var b=New(true);var ra=Send(a);var rb=Send(b);long delivery=Due(a,Order(a,ra.Id));At(a,delivery);At(b,delivery);Assert.Equal(DelegationMission.View(a,a.PlayerControl),DelegationMission.View(b,b.PlayerControl));long ack=Due(b,Reply(b,rb.Id));At(b,ack);Assert.Equal("refused",DelegationMission.View(b,b.PlayerControl).Single().Receipt);Assert.Empty(b.DiagnosticSnapshot().Delegation!.Plans);Assert.Empty(b.DiagnosticSnapshot().Delegation!.Arrivals);}
    [Fact] public void DeadlineIsCheckedAtReceiptWithoutInventingArrival(){var s=New(until:5);var r=Send(s);At(s,Due(s,Order(s,r.Id)));Assert.Empty(s.DiagnosticSnapshot().Delegation!.Plans);Assert.Equal("発送済・結果未確認",DelegationMission.View(s,s.PlayerControl).Single().Receipt);At(s,Due(s,Reply(s,r.Id)));Assert.Equal("authority-refused",DelegationMission.View(s,s.PlayerControl).Single().Receipt);Assert.Empty(s.DiagnosticSnapshot().Delegation!.Arrivals);}
    [Fact] public void DuplicateIdCannotExecuteOrSendAgain(){var s=New();var r=Send(s);var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.IssueRegional(r,s.Revision).Code);Assert.Equal(bytes,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.IdPayloadConflict,s.IssueRegional(r with{Action=RegionalAction.Hold},s.Revision).Code);At(s,Due(s,Order(s,r.Id)));Assert.Single(s.DiagnosticSnapshot().Delegation!.Plans);Assert.Equal(ResultCode.AlreadyAccepted,s.IssueRegional(r,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().Delegation!.Plans);}
    [Theory][InlineData(RegionalAction.Engage)][InlineData((RegionalAction)999)]
    public void NoOtherArmyAttackOrUnknownAction(RegionalAction action){var s=New();var r=DelegationMission.Build(s.DiagnosticSnapshot(),"request:bad",action);Assert.Equal(ResultCode.NotAvailable,s.IssueRegional(r,s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Region!.Commands);}
    [Fact] public void NewPlanMustNameKnownPredecessor(){var s=New();Send(s);var next=DelegationMission.Build(s.DiagnosticSnapshot(),"request:next",RegionalAction.Hold);Assert.Equal(ResultCode.NotAvailable,s.IssueRegional(next with{Supersedes=null},s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.IssueRegional(next,s.Revision).Code);}
    [Theory][InlineData(false)][InlineData(true)]
    public void PhysicallyLateOriginalCannotOverrideAppliedDescendant(bool lostMiddle){var s=New();var old=Send(s,"request:old");Assert.Equal(ResultCode.Accepted,s.HandleSupply(new("request:pack"),s.PlayerControl,true,FieldSupply.Capacity,s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);if(lostMiddle){var middle=Send(s,"request:middle");string message=Order(s,middle.Id);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,message));}var latest=Send(s,"request:new",RegionalAction.Hold);long first=Due(s,Order(s,latest.Id)),late=Due(s,Order(s,old.Id));Assert.True(first<late);At(s,first);Assert.Equal("applied",s.DiagnosticSnapshot().Region!.Commands.Single(c=>c.Request.Id==latest.Id).Result);At(s,late);var w=s.DiagnosticSnapshot();Assert.Equal("superseded",w.Region!.Commands.Single(c=>c.Request.Id==old.Id).Result);Assert.Single(w.Delegation!.Plans);Assert.Equal(latest.Id,w.Delegation.Plans.Single().Directive);Assert.All(w.Region.Units.Where(u=>u.Commander==ContractFixture.Clerk),u=>Assert.Equal(u.Home,u.Position));}
    [Theory][InlineData(0)][InlineData(10)][InlineData(30)][InlineData(60)][InlineData(150)]
    public void SaveRestorePreservesDeliveredPlansAndArrivalKnowledge(int at){var s=New();Send(s);At(s,at);s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"delegation-"+Guid.NewGuid().ToString("N")),s.DiagnosticSnapshot().Definitions);store.Save(s,"case",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));At(s,250);At(host.Current,250);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(DelegationMission.View(s,s.PlayerControl),DelegationMission.View(host.Current,host.Current.PlayerControl));}
    [Theory][InlineData("owner")][InlineData("agent")][InlineData("recipient")][InlineData("army")][InlineData("actions")][InlineData("address")]
    public void ForgedDelegationCannotLoad(string kind){var w=DelegationMission.Create();var t=w.Delegation!.Terms;w.Delegation=w.Delegation with{Terms=kind switch{"owner"=>t with{Owner=RetainerStart.House},"agent"=>t with{Agent=ContractFixture.Officer},"recipient"=>t with{Recipient=RegionalBattle.Enemy},"army"=>t with{Army=CreatedCampaign.Army},"actions"=>t with{Actions=[RegionalAction.Engage]},_=>t with{KnownAddress=new(0,0)}}};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void ArrivalContentIsFixedAfterLaterOrders(){var s=New();var first=Send(s);At(s,Due(s,Order(s,first.Id)));At(s,ArrivalTime(s,first.Id));var report=s.DiagnosticSnapshot().Delegation!.Arrivals.Single();var body=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==report.Message).Body;At(s,Due(s,report.Message));Send(s,"request:home",RegionalAction.Retreat);At(s,350);Assert.Equal(body,s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==report.Message).Body);}
    [Fact] public void OldProfilesCannotReceiveAnExtraArmyMandate(){var w=FieldPresence.Create();w.Delegation=DelegationMission.Create().Delegation;Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Theory][InlineData("position")][InlineData("soldiers")][InlineData("time")][InlineData("message")][InlineData("plan")]
    public void AlteredArrivalOrPlanCannotLoad(string kind){var s=New();var r=Send(s);At(s,Due(s,Order(s,r.Id)));At(s,ArrivalTime(s,r.Id));var w=s.DiagnosticSnapshot();var report=w.Delegation!.Arrivals.Single();if(kind=="position")report.Units[0]=report.Units[0] with{Position=new(0,0)};if(kind=="soldiers")report.Units[0]=report.Units[0] with{Soldiers=999};if(kind=="time")w.Delegation.Arrivals[0]=report with{At=report.At-1};if(kind=="message")w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id==report.Message?m with{Scope=ContractFixture.Village.Value}:m).ToArray();if(kind=="plan")w.Delegation.Plans[0].Units[0]=w.Delegation.Plans[0].Units[0] with{Goal=new(0,0)};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void LiteralOldPresenceInitialKeepsItsDefinition(){var w=ContractJson.Read<ContractWorld>(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","presence-d9f71d9-initial.json")));Assert.Null(w.Delegation);Assert.Equal(ContractJson.CanonicalHash(FieldPresence.Create("検証配置家臣")),ContractJson.CanonicalHash(w));}

}
